170	    if (!req.user.canDownload) {
171	      Logger.warn(`User "${req.user.username}" attempted to download without permission`)
172	      return res.sendStatus(403)
173	    }
174	    const libraryItemPath = req.libraryItem.path
175	    const itemTitle = req.libraryItem.media.title
176	
177	    Logger.info(`[LibraryItemController] User "${req.user.username}" requested download for item "${itemTitle}" at "${libraryItemPath}"`)
178	
179	    try {
180	      // If library item is a single file in root dir then no need to zip
181	      if (req.libraryItem.isFile) {
182	        // Express does not set the correct mimetype for m4b files so use our defined mimetypes if available
183	        const audioMimeType = getAudioMimeTypeFromExtname(Path.extname(libraryItemPath))
184	        if (audioMimeType) {
185	          res.setHeader('Content-Type', audioMimeType)
186	        }
187	        await new Promise((resolve, reject) => res.download(libraryItemPath, req.libraryItem.relPath, (error) => (error ? reject(error) : resolve())))
188	      } else {
189	        const filename = `${itemTitle}.zip`
190	        await zipHelpers.zipDirectoryPipe(libraryItemPath, filename, res)
191	      }
192	      Logger.info(`[LibraryItemController] Downloaded item "${itemTitle}" at "${libraryItemPath}"`)
193	    } catch (error) {
194	      Logger.error(`[LibraryItemController] Download failed for item "${itemTitle}" at "${libraryItemPath}"`, error)
195	      LibraryItemController.handleDownloadError(error, res)
196	    }
197	  }
