199	  /**
200	   * PATCH: /items/:id/media
201	   * Update media for a library item. Will create new authors & series when necessary
202	   *
203	   * @this {import('../routers/ApiRouter')}
204	   *
205	   * @param {LibraryItemControllerRequest} req
206	   * @param {Response} res
207	   */
208	  async updateMedia(req, res) {
209	    const mediaPayload = req.body
210	
211	    if (mediaPayload.url) {
212	      await LibraryItemController.prototype.uploadCover.bind(this)(req, res, false)
213	      if (res.writableEnded || res.headersSent) return
214	    }
215	
216	    // Podcast specific
217	    let isPodcastAutoDownloadUpdated = false
218	    if (req.libraryItem.isPodcast) {
219	      if (mediaPayload.autoDownloadEpisodes !== undefined && req.libraryItem.media.autoDownloadEpisodes !== mediaPayload.autoDownloadEpisodes) {
220	        isPodcastAutoDownloadUpdated = true
221	      } else if (mediaPayload.autoDownloadSchedule !== undefined && req.libraryItem.media.autoDownloadSchedule !== mediaPayload.autoDownloadSchedule) {
222	        isPodcastAutoDownloadUpdated = true
223	      }
224	
225	      if (mediaPayload.autoDownloadSchedule && !cron.validate(mediaPayload.autoDownloadSchedule)) {
226	        Logger.error(`[LibraryItemController] Invalid auto download schedule cron expression "${mediaPayload.autoDownloadSchedule}" for library item "${req.libraryItem.media.title}"`)
227	        return res.status(400).send('Invalid auto download schedule cron expression')
228	      }
229	    }
230	
231	    let hasUpdates = (await req.libraryItem.media.updateFromRequest(mediaPayload)) || mediaPayload.url
232	
233	    if (req.libraryItem.isBook && Array.isArray(mediaPayload.metadata?.series)) {
234	      const seriesUpdateData = await req.libraryItem.media.updateSeriesFromRequest(mediaPayload.metadata.series, req.libraryItem.libraryId)
235	      if (seriesUpdateData?.seriesRemoved.length) {
236	        // Check remove empty series
237	        Logger.debug(`[LibraryItemController] Series were removed from book. Check if series are now empty.`)
238	        await this.checkRemoveEmptySeries(seriesUpdateData.seriesRemoved.map((se) => se.id))
239	      }
240	      if (seriesUpdateData?.seriesAdded.length) {
241	        // Add series to filter data
242	        seriesUpdateData.seriesAdded.forEach((se) => {
243	          Database.addSeriesToFilterData(req.libraryItem.libraryId, se.name, se.id)
244	        })
245	      }
246	      if (seriesUpdateData?.hasUpdates) {
247	        hasUpdates = true
248	      }
249	    }
250	
251	    if (req.libraryItem.isBook && Array.isArray(mediaPayload.metadata?.authors)) {
252	      const authorNames = mediaPayload.metadata.authors.map((au) => (typeof au.name === 'string' ? au.name.trim() : null)).filter((au) => au)
253	      const authorUpdateData = await req.libraryItem.media.updateAuthorsFromRequest(authorNames, req.libraryItem.libraryId)
254	      if (authorUpdateData?.authorsRemoved.length) {
255	        // Check remove empty authors
256	        Logger.debug(`[LibraryItemController] Authors were removed from book. Check if authors are now empty.`)
257	        await this.checkRemoveAuthorsWithNoBooks(authorUpdateData.authorsRemoved.map((au) => au.id))
258	        hasUpdates = true
259	      }
260	      if (authorUpdateData?.authorsAdded.length) {
261	        // Add authors to filter data
262	        authorUpdateData.authorsAdded.forEach((au) => {
263	          Database.addAuthorToFilterData(req.libraryItem.libraryId, au.name, au.id)
264	        })
265	        hasUpdates = true
266	      }
267	    }
268	
269	    if (hasUpdates) {
270	      req.libraryItem.changed('updatedAt', true)
271	      await req.libraryItem.save()
272	
273	      await req.libraryItem.saveMetadataFile()
274	
275	      if (isPodcastAutoDownloadUpdated) {
276	        this.cronManager.checkUpdatePodcastCron(req.libraryItem)
277	      }
278	
279	      Logger.debug(`[LibraryItemController] Updated library item media ${req.libraryItem.media.title}`)
280	      SocketAuthority.libraryItemEmitter('item_updated', req.libraryItem)
281	    }
282	    res.json({
283	      updated: hasUpdates,
284	      libraryItem: req.libraryItem.toOldJSON()
285	    })
286	  }
