479	   * @param {Response} res
480	   */
481	  async updateTracks(req, res) {
482	    const orderedFileData = req.body?.orderedFileData
483	
484	    if (!req.libraryItem.isBook) {
485	      Logger.error(`[LibraryItemController] updateTracks invalid media type ${req.libraryItem.id}`)
486	      return res.sendStatus(400)
487	    }
488	    if (!Array.isArray(orderedFileData) || !orderedFileData.length) {
489	      Logger.error(`[LibraryItemController] updateTracks invalid orderedFileData ${req.libraryItem.id}`)
490	      return res.sendStatus(400)
491	    }
492	    // Ensure that each orderedFileData has a valid ino and is in the book audioFiles
493	    if (orderedFileData.some((fileData) => !fileData?.ino || !req.libraryItem.media.audioFiles.some((af) => af.ino === fileData.ino))) {
494	      Logger.error(`[LibraryItemController] updateTracks invalid orderedFileData ${req.libraryItem.id}`)
495	      return res.sendStatus(400)
496	    }
497	
498	    let index = 1
499	    const updatedAudioFiles = orderedFileData.map((fileData) => {
500	      const audioFile = req.libraryItem.media.audioFiles.find((af) => af.ino === fileData.ino)
501	      audioFile.manuallyVerified = true
502	      audioFile.exclude = !!fileData.exclude
503	      if (audioFile.exclude) {
504	        audioFile.index = -1
505	      } else {
506	        audioFile.index = index++
507	      }
508	      return audioFile
509	    })
510	    updatedAudioFiles.sort((a, b) => a.index - b.index)
511	
512	    req.libraryItem.media.audioFiles = updatedAudioFiles
513	    req.libraryItem.media.changed('audioFiles', true)
514	    await req.libraryItem.media.save()
515	
516	    SocketAuthority.libraryItemEmitter('item_updated', req.libraryItem)
517	    res.json(req.libraryItem.toOldJSON())
518	  }
