type EpisodeUpdateBody = {
  enclosure?: { url?: unknown; type?: unknown; length?: unknown } | null
  [key: string]: unknown // index signature: updateEpisode() reads and assigns req.body by a dynamic key
}

// The library file that create() adds for a downloaded cover: it has fileType and no isSupplementary, which the LibraryFileObject typedef of LibraryItem.js (JS) does not describe
type CoverLibraryFile = Omit<LibraryItem['libraryFiles'][number], 'isSupplementary'> & { fileType: string }
// The two inherited Sequelize statics that this controller calls on the LibraryItem model (used by the casts in create()). The created item's libraryFiles also take the cover file
type LibraryItemCount = { count(options: CountOptions): Promise<number> }
type LibraryItemCreate = { create(values: CreationAttributes<LibraryItem>, options: CreateOptions): Promise<LibraryItem & { libraryFiles: CoverLibraryFile[] }> }
// downloadCoverFromUrlNew() resolves with { error } or { cover }; the code reads both keys
type CoverDownloadResult = { error?: string; cover?: string }

